const incoming = $json.body && typeof $json.body === 'object' && !Array.isArray($json.body)
  ? $json.body
  : $json;

const clean = (value, max = 500) => {
  if (value === undefined || value === null) return null;
  const normalized = String(value).trim();
  return normalized ? normalized.slice(0, max) : null;
};

const patientInput = incoming.patient && typeof incoming.patient === 'object'
  ? incoming.patient
  : {};

const metadata = incoming.metadata && typeof incoming.metadata === 'object' && !Array.isArray(incoming.metadata)
  ? incoming.metadata
  : {};

const normalized = {
  message_id: clean(incoming.message_id ?? incoming.idempotency_key, 160),
  intent: clean(incoming.intent, 50)?.toLowerCase() ?? null,
  patient: {
    name: clean(patientInput.name ?? incoming.patient_name, 120),
    phone: clean(patientInput.phone ?? incoming.phone, 30),
  },
  doctor_code: clean(incoming.doctor_code, 40)?.toUpperCase() ?? null,
  preferred_date: clean(incoming.preferred_date, 10),
  time_window: clean(incoming.time_window, 20)?.toLowerCase() ?? null,
  slot_id: clean(incoming.slot_id, 50),
  new_slot_id: clean(incoming.new_slot_id, 50),
  appointment_id: clean(incoming.appointment_id, 50),
  brief_reason: clean(incoming.brief_reason, 500),
  late_minutes: incoming.late_minutes ?? null,
  language: clean(incoming.language, 20)?.toLowerCase() ?? 'unknown',
  source: clean(incoming.source, 40)?.toLowerCase() ?? 'day33_test',
  metadata,
};

return [{ json: normalized }];

const request = { ...$json };
const errors = [];
const supportedIntents = new Set([
  'list_slots',
  'book',
  'reschedule',
  'cancel',
  'check_appointment',
  'confirm_attendance',
  'report_late',
  'join_waitlist',
  'check_queue_status',
]);
const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const datePattern = /^\d{4}-\d{2}-\d{2}$/;

const hasValidPhone = () => {
  const digits = String(request.patient?.phone ?? '').replace(/\D/g, '');
  return digits.length >= 10 && digits.length <= 15 && !/^0+$/.test(digits);
};
const requirePhone = () => {
  if (!hasValidPhone()) errors.push('patient.phone must contain 10 to 15 digits');
};
const requirePatientName = () => {
  const length = String(request.patient?.name ?? '').trim().length;
  if (length < 2 || length > 120) errors.push('patient.name must contain 2 to 120 characters');
};
const requireUuid = (field) => {
  if (!uuidPattern.test(String(request[field] ?? ''))) errors.push(`${field} must be a valid UUID`);
};
const requireDate = () => {
  if (!datePattern.test(String(request.preferred_date ?? ''))) {
    errors.push('preferred_date must use YYYY-MM-DD');
    return;
  }
  const parsed = new Date(`${request.preferred_date}T00:00:00Z`);
  if (Number.isNaN(parsed.getTime()) || parsed.toISOString().slice(0, 10) !== request.preferred_date) {
    errors.push('preferred_date is not a real calendar date');
  }
};

if (!request.message_id) errors.push('message_id is required');
if (request.message_id && !/^[A-Za-z0-9._:-]{3,160}$/.test(request.message_id)) {
  errors.push('message_id contains unsupported characters');
}
if (!request.intent) errors.push('intent is required');
if (request.intent && !supportedIntents.has(request.intent)) {
  errors.push(`unsupported intent: ${request.intent}`);
}

if (supportedIntents.has(request.intent)) {
  switch (request.intent) {
    case 'list_slots':
      if (!/^DR-[A-Z0-9_-]{2,30}$/.test(String(request.doctor_code ?? ''))) {
        errors.push('doctor_code must use a verified code such as DR-USMAN');
      }
      requireDate();
      break;
    case 'book':
      requirePatientName();
      requirePhone();
      requireUuid('slot_id');
      break;
    case 'reschedule':
      requirePhone();
      requireUuid('appointment_id');
      requireUuid('new_slot_id');
      break;
    case 'cancel':
    case 'confirm_attendance':
      requirePhone();
      requireUuid('appointment_id');
      break;
    case 'report_late':
      requirePhone();
      requireUuid('appointment_id');
      if (!Number.isInteger(Number(request.late_minutes)) || Number(request.late_minutes) < 1 || Number(request.late_minutes) > 360) {
        errors.push('late_minutes must be an integer from 1 to 360');
      } else {
        request.late_minutes = Number(request.late_minutes);
      }
      break;
    case 'join_waitlist':
      requirePatientName();
      requirePhone();
      if (!/^DR-[A-Z0-9_-]{2,30}$/.test(String(request.doctor_code ?? ''))) {
        errors.push('doctor_code must use a verified code such as DR-USMAN');
      }
      requireDate();
      if (request.time_window && !['morning', 'afternoon', 'evening', 'any'].includes(request.time_window)) {
        errors.push('time_window must be morning, afternoon, evening or any');
      }
      break;
    case 'check_appointment':
    case 'check_queue_status':
      requirePhone();
      if (request.appointment_id) requireUuid('appointment_id');
      break;
  }
}

if (request.brief_reason && request.brief_reason.length > 500) {
  errors.push('brief_reason must not exceed 500 characters');
}

return [{
  json: {
    ...request,
    valid: errors.length === 0,
    validation: {
      valid: errors.length === 0,
      errors,
      checked_at: new Date().toISOString(),
    },
  },
}];

return [{
  json: {
    http_status: 400,
    body: {
      ok: false,
      error_code: 'VALIDATION_FAILED',
      message: 'The request did not match the ClinicFlow core contract',
      errors: $json.validation?.errors ?? ['Unknown validation error'],
      message_id: $json.message_id ?? null,
    },
  },
}];

let result = $json.result;

if (typeof result === 'string') {
  try {
    result = JSON.parse(result);
  } catch {
    result = {
      ok: false,
      error_code: 'INVALID_DATABASE_RESPONSE',
      message: 'The database returned an invalid response',
    };
  }
}

if (!result || typeof result !== 'object' || Array.isArray(result)) {
  result = {
    ok: false,
    error_code: 'EMPTY_DATABASE_RESPONSE',
    message: 'The database returned no usable result',
  };
}

const statusByCode = {
  DOCTOR_NOT_FOUND: 404,
  SLOT_NOT_FOUND: 404,
  APPOINTMENT_NOT_FOUND: 404,
  QUEUE_ENTRY_NOT_FOUND: 404,
  SLOT_UNAVAILABLE: 409,
  DOCTOR_UNAVAILABLE: 409,
  APPOINTMENT_NOT_RESCHEDULABLE: 409,
  APPOINTMENT_NOT_CANCELLABLE: 409,
  APPOINTMENT_NOT_CONFIRMABLE: 409,
  APPOINTMENT_NOT_ELIGIBLE: 409,
  CORE_DATABASE_ERROR: 503,
};

return [{
  json: {
    http_status: result.ok === true ? 200 : (statusByCode[result.error_code] ?? 400),
    body: result,
  },
}];
